    allies = observation.get('allies', [])
    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    territory = observation.get('territory', [])
    agent_pos = player.get('pos', [0, 0])

    # Defensive getters for optional fields
    def get_field(obj, key, default):
        return obj.get(key, default)

    def is_valid(pos):
        x, y = pos
        return 0 <= x < width and 0 <= y < height

    def neighbors(pos):
        x, y = pos
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            new_pos = [x + dx, y + dy]
            if is_valid(new_pos):
                yield new_pos

    def closest(targets):
        min_dist = float('inf')
        target_pos = None
        for t in targets:
            dist = abs(t[0] - agent_pos[0]) + abs(t[1] - agent_pos[1])
            if dist < min_dist:
                min_dist = dist
                target_pos = t
        return target_pos

    # Find nearest resource and enemy using existing heuristic
    resource_targets = resources if resources else []
    enemy_targets = enemies if enemies else []

    target_resource = closest(resource_targets) if resource_targets else None
    target_enemy = closest(enemy_targets) if enemy_targets else None

    # Priority: resource collection over pursuit
    target = None
    if target_resource:
        target = target_resource
    elif target_enemy:
        target = target_enemy
    else:
        target = agent_pos  # default to staying in place

    delta_x = target[0] - agent_pos[0]
    delta_y = target[1] - agent_pos[1]

    # Decide move towards target
    if abs(delta_x) >= abs(delta_y) and delta_x != 0:
        dx = 1 if delta_x > 0 else -1
        dy = 0
    elif delta_y != 0:
        dx = 0
        dy = 1 if delta_y > 0 else -1
    else:
        dx = 0
        dy = 0

    # Check move validity
    new_pos = [agent_pos[0] + dx, agent_pos[1] + dy]
    if not is_valid(new_pos):
        # Try alternative axis move
        if abs(delta_x) >= abs(delta_y) and delta_y != 0:
            alt_dx, alt_dy = 0, 1 if delta_y > 0 else -1
        elif delta_x != 0:
            alt_dx, alt_dy = 1 if delta_x > 0 else -1, 0
        else:
            alt_dx, alt_dy = 0, 0

        alt_pos = [agent_pos[0] + alt_dx, agent_pos[1] + alt_dy]
        if is_valid(alt_pos):
            dx, dy = alt_dx, alt_dy
        else:
            # No valid move, stay in place
            dx, dy = 0, 0

    return [dx, dy]

